#include <cstdint>
#include <cstring>
#include <string>
#include <iostream>

// Test implementation of PutVarint64
void PutVarint64(std::string* dst, uint64_t v) {
    while (v >= 128) {
        // Encode 7 bits in each byte, with continuation bit set
        dst->push_back(static_cast<char>((v & 0x7F) | 0x80));
        v >>= 7;
    }
    dst->push_back(static_cast<char>(v & 0x7F));
}

// Helper to decode and verify
uint64_t GetVarint64(const std::string& src, size_t& pos) {
    uint64_t result = 0;
    int shift = 0;
    while (pos < src.size()) {
        uint64_t byte = static_cast<unsigned char>(src[pos++]);
        if (byte & 0x80) {
            result |= ((byte & 0x7F) << shift);
            shift += 7;
        } else {
            result |= (byte << shift);
            break;
        }
    }
    return result;
}

int main() {
    // Test cases
    std::vector<uint64_t> test_values = {
        0, 1, 127, 128, 255, 256, 1000, 10000,
        (1ULL << 14) - 1,  // 16383
        1ULL << 14,         // 16384
        (1ULL << 21) - 1,  // 2097151
        1ULL << 21,         // 2097152
        (1ULL << 28) - 1,  // 268435455
        1ULL << 28,         // 268435456
        (1ULL << 35) - 1,
        1ULL << 35,
        (1ULL << 42) - 1,
        1ULL << 42,
        (1ULL << 49) - 1,
        1ULL << 49,
        (1ULL << 56) - 1,
        1ULL << 56,
        (1ULL << 63) - 1,
        1ULL << 63,
        UINT64_MAX
    };

    bool all_passed = true;
    for (uint64_t v : test_values) {
        std::string encoded;
        PutVarint64(&encoded, v);

        size_t pos = 0;
        uint64_t decoded = GetVarint64(encoded, pos);

        if (decoded != v) {
            std::cout << "FAIL: " << v << " -> encoded size " << encoded.size() 
                      << " -> decoded " << decoded << std::endl;
            all_passed = false;
        } else {
            std::cout << "PASS: " << v << " -> encoded size " << encoded.size() << std::endl;
        }
    }

    return all_passed ? 0 : 1;
}

