#include <cstdint>
#include <cstring>
#include <string>
#include <vector>
#include <iostream>

// Test implementation of PutVarint64
void PutVarint64(std::string* dst, uint64_t v) {
    while (v >= 128) {
        dst->push_back(static_cast<char>((v & 0x7F) | 0x80));
        v >>= 7;
    }
    dst->push_back(static_cast<char>(v & 0x7F));
}

// Helper to decode and verify
uint64_t GetVarint64(const std::string& src, size_t* pos) {
    uint64_t result = 0;
    int shift = 0;
    while (*pos < src.size()) {
        uint64_t byte = static_cast<unsigned char>(src[*pos]);
        (*pos)++;
        if (byte & 0x80) {
            result |= ((byte & 0x7F) << shift);
            shift += 7;
        } else {
            result |= (byte << shift);
            break;
        }
    }
    return result;
}

int main() {
    std::vector<uint64_t> test_values;
    test_values.push_back(0);
    test_values.push_back(1);
    test_values.push_back(127);
    test_values.push_back(128);
    test_values.push_back(255);
    test_values.push_back(256);
    test_values.push_back(1000);
    test_values.push_back(10000);
    test_values.push_back((1ULL << 14) - 1);
    test_values.push_back(1ULL << 14);
    test_values.push_back((1ULL << 21) - 1);
    test_values.push_back(1ULL << 21);
    test_values.push_back((1ULL << 28) - 1);
    test_values.push_back(1ULL << 28);
    test_values.push_back((1ULL << 35) - 1);
    test_values.push_back(1ULL << 35);
    test_values.push_back((1ULL << 42) - 1);
    test_values.push_back(1ULL << 42);
    test_values.push_back((1ULL << 49) - 1);
    test_values.push_back(1ULL << 49);
    test_values.push_back((1ULL << 56) - 1);
    test_values.push_back(1ULL << 56);
    test_values.push_back((1ULL << 63) - 1);
    test_values.push_back(1ULL << 63);
    test_values.push_back(UINT64_MAX);

    bool all_passed = true;
    for (size_t i = 0; i < test_values.size(); i++) {
        uint64_t v = test_values[i];
        std::string encoded;
        PutVarint64(&encoded, v);

        size_t pos = 0;
        uint64_t decoded = GetVarint64(encoded, &pos);

        if (decoded != v) {
            std::cout << "FAIL: " << v << " -> encoded size " << encoded.size() 
                      << " -> decoded " << decoded << std::endl;
            all_passed = false;
        } else {
            std::cout << "PASS: " << v << " -> encoded size " << encoded.size() << std::endl;
